    for i in range(H):
        c=Counter(I[i]); v,_=c.most_common(1)[0]
        if c[v]>=W-2: sep_rows.append(v)
    for j in range(W):
        c=Counter(I[:,j]); v,_=c.most_common(1)[0]
        if c[v]>=H-2: sep_cols.append(v)
    lc=Counter(sep_rows).most_common(1)[0][0]
    fill=cnt.most_common(1)[0][0]
    mr=[i for i in range(H) if I[i,0]==lc and len({int(x) for x in I[i] if int(x)!=fill})>=1]
    mc=[j for j in range(W) if I[0,j]==lc and len({int(x) for x in I[:,j] if int(x)!=fill})>=1]
    out=[]
    for a,b in zip(mr,mr[1:]):
        row=[]
        for c,d in zip(mc,mc[1:]):
            cs=(int(I[a,c]),int(I[a,d]),int(I[b,c]),int(I[b,d]))
            ncz=Counter(cs).most_common()
            top,k1=ncz[0]; second=None
            if len(ncz)>1: second=list(ncz[1])[0]
            if top!=fill:
                if k1==4: row.append(top)
                elif k1==3 or (second is not None and k1==2 and second!=top): row.append(top)
                else: row.append(fill)
            else: row.append(fill)
        out.append(row)
    return out
